```hcl
# Enforce IMDSv2 on an EC2 instance
resource "aws_instance" "<example_resource_name>" {
  ami           = "<example_resource_id>"
  instance_type = "<example_resource_name>"

  metadata_options {
    http_tokens = "required"  # Critical: Require IMDSv2 tokens (blocks IMDSv1)
  }
}
```

```hcl
# Terraform: restrict SSH from the Internet
resource "aws_security_group" "<example_resource_name>" {
  vpc_id = "<example_resource_id>"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/8"]  # Critical: do not use 0.0.0.0/0 or ::/0
  }
}
```

